import {useCallback,useEffect,useState} from 'react';
export const useChannel=(origin,notify)=>{
  const [frame,setFrame]=useState(null);
  const post=useCallback((packet)=>{
    if(frame?.contentWindow) {
      frame.contentWindow?.postMessage(packet,origin);
    }
  },[origin,frame]);
  useEffect(()=>{
    const listener=(event)=>{
      if(!frame) {return;}
      if(event.source!==frame?.contentWindow) {return;}
      if(event.data.kind==='control') {post({kind:'control-reply',value:null});}
      if(notify) {notify(event.data,post);}
    };
    window.addEventListener('message',listener,false);
    return ()=>{window.removeEventListener('message',listener,false);};
  },[notify,frame,post]);
  return {transmit:post,bindFrame:setFrame};
};

