import {forwardRef as bridgeRef} from 'react';
import {Card as Surface} from '@sanity/ui';
const visibleStyle={display:'flex'};
const hiddenStyle={display:'none'};
export const Frame=bridgeRef(function ForwardedFrame(props,forwarded){
  const {src,hidden}=props;
  return <Surface style={hidden?hiddenStyle:visibleStyle}>
    <iframe ref={forwarded} src={src} style={{border:'none'}}/>
  </Surface>;
});
